body::before {
  content: "LEAKY BLACK ON TOP DUMB NIGGAS";
  position: fixed;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 999999999;
  padding: 8px 18px;

  background: #000000 !important;
  color: #ffffff !important;
  border: 1px solid #3a3a3a;
  border-radius: 8px;

